UPDATE ai_conversation_generation_payload
SET upstream_request_id = #{upstreamRequestId,jdbcType=VARCHAR},
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE generation_id = #{generationId,jdbcType=BINARY}
  AND (
      upstream_request_id IS NULL
      OR upstream_request_id = #{upstreamRequestId,jdbcType=VARCHAR}
  )

